package ma.seatflow;
import ma.seatflow.reservation.ReservationService;import ma.seatflow.seasonpass.PassController;import ma.seatflow.shared.ApiError.Conflict;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.containers.PostgreSQLContainer;import java.util.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest class ReservationConcurrencyTest {
 static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("seatflow").withUsername("seatflow").withPassword("test");static{postgres.start();}
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired ReservationService service;@Autowired PassController passes;@Autowired JdbcTemplate db;
 long es(int seat){return db.queryForObject("SELECT id FROM event_seat WHERE event_id=1 AND seat_id=?",Long.class,seat);}
 @Test void hundredConcurrentAttemptsOnlyOneHold() throws Exception {long seat=es(3);for(int repeat=0;repeat<3;repeat++){db.update("DELETE FROM seat_hold WHERE event_seat_id=?",seat);var pool=Executors.newFixedThreadPool(100);var ready=new CountDownLatch(100);var start=new CountDownLatch(1);var jobs=new ArrayList<Future<Boolean>>();for(int i=0;i<100;i++)jobs.add(pool.submit(()->{ready.countDown();start.await();try{service.hold("client",new ReservationService.HoldRequest(1,List.of(seat)));return true;}catch(Conflict e){return false;}}));assertTrue(ready.await(15,TimeUnit.SECONDS));start.countDown();int successes=0;for(var job:jobs)if(job.get(60,TimeUnit.SECONDS))successes++;pool.shutdown();assertEquals(1,successes);assertEquals(1L,db.queryForObject("SELECT count(*) FROM seat_hold WHERE event_seat_id=? AND status='ACTIVE' AND expires_at>now()",Long.class,seat));}}
 @Test void multiSeatHoldIsAtomic(){long a=es(4),b=es(5);db.update("DELETE FROM seat_hold WHERE event_seat_id IN (?,?)",a,b);service.hold("client",new ReservationService.HoldRequest(1,List.of(a)));assertThrows(Conflict.class,()->service.hold("abonne",new ReservationService.HoldRequest(1,List.of(a,b))));assertEquals(0L,db.queryForObject("SELECT count(*) FROM seat_hold WHERE event_seat_id=? AND status='ACTIVE'",Long.class,b));}
 @Test void expiredHoldDoesNotBlock(){long seat=es(6);db.update("DELETE FROM seat_hold WHERE event_seat_id=?",seat);db.update("INSERT INTO seat_hold(event_seat_id,owner_id,token,expires_at,status) VALUES(?,1,gen_random_uuid(),now()-interval '1 minute','ACTIVE')",seat);service.hold("client",new ReservationService.HoldRequest(1,List.of(seat)));assertEquals(1L,db.queryForObject("SELECT count(*) FROM seat_hold WHERE event_seat_id=? AND status='ACTIVE'",Long.class,seat));}
 @Test void fixedPassCannotTakeHeldSeat(){assertThrows(Conflict.class,()->passes.buy(()->"client",new PassController.PassRequest(1,"FIXED",2L)));}
 @Test void fixedPassProtectsEveryEligibleEvent(){var result=passes.buy(()->"client",new PassController.PassRequest(1,"FIXED",7L));assertEquals("FIXED",result.get("type"));assertEquals(2L,db.queryForObject("SELECT count(*) FROM event_seat WHERE seat_id=7 AND event_id IN (1,3) AND status='PASS'",Long.class));assertEquals(2L,db.queryForObject("SELECT count(*) FROM ticket t JOIN event_seat es ON es.id=t.event_seat_id WHERE es.seat_id=7 AND es.event_id IN (1,3)",Long.class));}
}
